INSERT INTO user_notifications(notification_id,user_id,actor_id,notification_type,title,content,target_type,target_id,post_id,created_at)
SELECT user_notifications_seq.NEXTVAL,u.user_id,#{actorId},#{type},#{title},#{content},#{targetType,jdbcType=VARCHAR},#{targetId,jdbcType=NUMERIC},#{postId,jdbcType=NUMERIC},SYSDATE
FROM users u WHERE UPPER(TRIM(u.is_admin)) IN ('Y','YES','TRUE','1','ADMIN') AND u.user_id<>#{actorId}
